report DeviceModels "Device Model and Loan Analysis"
  by dimension
  date purchase_date
  entity device_model_loan_analysis
  role view_reports
  currency KES
  cache 60
  maxrange 1200

  group model_name
  rows "Device Model"
  sort loans desc

  devices = count devices_list "Devices"
  loans = count loans "Loans Issued"
  principal = sum loans.principal "Principal Lent" money
  deposits = sum loans.deposit "Deposits Received" money
  installment = sum loans.installment_amount "Installment Amount" money
  paid = sum loans.total_paid "Total Repaid" money
  balance = sum loans.balance "Outstanding Balance" money

  headline {label}: {devices} devices, {loans} loans issued and {principal} financed.

  remark devices == 0 | watch | No devices | No devices were recorded for {label}.
  remark loans == 0 | watch | No loans for model | No loans were issued for {label}.
  remark balance > principal | bad | Outstanding exposure | {label} has an outstanding balance of {balance}.
  remark true | neutral | Model performance | {label}: {loans} loans, {paid} repaid and {balance} outstanding.
